mapper.update:
UPDATE report_template
SET del_flag = '0', update_time = NOW()
WHERE template_id = #{templateId}

mapper.select:
SELECT pt.template_id AS templateId, pt.product_id AS productId, pc.product_bio AS productBio, pc.product_name AS productName, pc.product_code AS productCode FROM product_template pt JOIN product_config pc ON pc.id = pt.product_id AND pc.del_flag = '0' WHERE pt.del_flag = '0' AND pt.template_id IN
#{id}
ORDER BY pt.template_id, pt.sort_order, pt.id

SELECT pt.product_id AS productId, pc.product_name AS productName, t.template_id AS templateId, t.template_name AS templateName FROM product_template pt JOIN report_template t ON t.template_id = pt.template_id AND t.del_flag = '0' AND t.status = 'active' JOIN product_config pc ON pc.id = pt.product_id AND pc.del_flag = '0' WHERE pt.del_flag = '0' AND pt.enabled = 1 AND t.project_id = #{projectId} AND pt.product_id IN
#{pid}
AND t.template_id != #{excludeTemplateId}
ORDER BY pt.product_id

mapper.update:
UPDATE product_template
SET del_flag = '0', enabled = 1, sort_order = #{sortOrder}, update_time = NOW()
WHERE template_id = #{templateId} AND product_id = #{productId}
